#!/usr/bin/env python3
"""
HOOPSPHERE PLAYER PROGRESS REPORT GENERATOR
Self-contained. Produces the final parent-ready PDF from evaluator form data.
Set by HoopSphere ops. Do not restyle, redesign, or "improve" the layout.

USAGE (inside the Claude Project):
    exec(open('generator.py').read())
    path = generate(data, flyer_path=None)

DATA SCHEMA for REPORT_TYPE = 'AAU' (this file's active type):
    data = {
      'player': 'Jordan M.',
      'date': '08/25/2026',
      'scores': {                      # flat dict, one int (1|2|3) per theme,
        'Defense': int,                # keyed by these EXACT six names
        'Scoring': int,
        'Ball Handling & Footwork': int,
        'IQ': int,
        'Conditioning / Strength': int,
        'Mentality': int,
      },
      'doing_well': [str],             # ONE item: coach's entry, completed by Claude
      'to_work_on': [str],             # ONE item: coach's entry, completed by Claude
      'coachs_note': str,              # coach's note, completed/expanded by Claude
    }
    No recommendation, no flyers: the finished PDF is always exactly 2 pages.
    (The AAU/STANDARD/FOUNDATIONS branches below use the legacy
     card-title -> [int, int, int] schema and are inactive here.)
"""

REPORT_TYPE = 'AAU'   # 'AAU' | 'STANDARD' | 'FOUNDATIONS'  (set per Project)

# ---------- bootstrap ----------
import subprocess, sys, os, base64, re, urllib.request, tempfile

def _ensure(mod, pip=None):
    try:
        __import__(mod)
    except ImportError:
        subprocess.run([sys.executable, '-m', 'pip', 'install', pip or mod,
                        '--break-system-packages', '--timeout', '30', '--retries', '2', '-q'], check=True)

_ensure('reportlab')
_ensure('fontTools', 'fonttools')

from reportlab.lib.pagesizes import letter
from reportlab.pdfgen import canvas
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.colors import HexColor
from reportlab.lib.utils import simpleSplit, ImageReader

# ---------- fonts ----------
FONT_DIR = '/tmp/hs_fonts'
_GF = 'https://raw.githubusercontent.com/google/fonts/main/ofl'
FONT_FILES = {
    'Anton':  f'{_GF}/anton/Anton-Regular.ttf',
    'BCMed':  f'{_GF}/barlowcondensed/BarlowCondensed-Medium.ttf',
    'BCSemi': f'{_GF}/barlowcondensed/BarlowCondensed-SemiBold.ttf',
    'BCBold': f'{_GF}/barlowcondensed/BarlowCondensed-Bold.ttf',
    'B':      f'{_GF}/barlow/Barlow-Regular.ttf',
    'BMed':   f'{_GF}/barlow/Barlow-Medium.ttf',
    'BSemi':  f'{_GF}/barlow/Barlow-SemiBold.ttf',
    'BBold':  f'{_GF}/barlow/Barlow-Bold.ttf',
    'BItal':  f'{_GF}/barlow/Barlow-Italic.ttf',
}

_DL_CLOCK = {'spent': 0.0}
_DL_BUDGET = 180.0   # seconds allowed for ALL downloads in one run, then fail loudly

def _download(url, dest, attempts=4, timeout=25):
    """Download with per-request timeouts, bounded retries, and a global time budget.
    Never hangs: a stalled connection raises within `timeout` seconds."""
    import time, random, socket
    last = None
    for i in range(attempts):
        if _DL_CLOCK['spent'] > _DL_BUDGET:
            raise RuntimeError(
                'Download budget exhausted (%ds). The sandbox cannot reach %s right now. '
                'Tell the evaluator generation is blocked by network, not by their data, and retry in a fresh chat.'
                % (_DL_BUDGET, url.split('/')[2]))
        t0 = time.time()
        try:
            req = urllib.request.Request(url, headers={'User-Agent': 'hoopsphere-report-generator'})
            with urllib.request.urlopen(req, timeout=timeout) as r, open(dest, 'wb') as f:
                while True:
                    chunk = r.read(65536)
                    if not chunk:
                        break
                    f.write(chunk)
            _DL_CLOCK['spent'] += time.time() - t0
            return
        except Exception as e:
            _DL_CLOCK['spent'] += time.time() - t0
            last = e
            code = getattr(e, 'code', None)
            if code is not None and code not in (403, 429, 500, 502, 503, 504):
                break
            time.sleep(min(1.5 * (2 ** i) + random.random(), 8))
    raise RuntimeError('Could not download %s after %d attempts: %s' % (url, attempts, last))

def _ensure_fonts():
    os.makedirs(FONT_DIR, exist_ok=True)
    for name, url in FONT_FILES.items():
        p = os.path.join(FONT_DIR, name + '.ttf')
        if not os.path.exists(p):
            _download(url, p)
        try:
            pdfmetrics.getFont(name)
        except Exception:
            pdfmetrics.registerFont(TTFont(name, p))

_ensure_fonts()

# ---------- logo (embedded) ----------
LOGO_B64 = ""
_logo_path = '/tmp/hs_logo.png'
if not os.path.exists(_logo_path):
    open(_logo_path, 'wb').write(base64.b64decode(LOGO_B64))
LOGO = ImageReader(_logo_path)

# ---------- precise digit centering ----------
from fontTools.ttLib import TTFont as _FT
from fontTools.pens.boundsPen import BoundsPen as _BP
_ft = _FT(os.path.join(FONT_DIR, 'BCBold.ttf'))
_upm = _ft['head'].unitsPerEm
_gs = _ft.getGlyphSet()
_cmap = _ft.getBestCmap()
_DB = {}
for _ch in '123':
    _p = _BP(_gs)
    _gs[_cmap[ord(_ch)]].draw(_p)
    _DB[_ch] = _p.bounds

def centered_digit(c, cx, cy, ch, size, color):
    x0, y0, x1, y1 = _DB[ch]
    s = size/_upm
    c.setFont('BCBold', size)
    c.setFillColor(color)
    c.drawString(cx - (x1+x0)*s/2, cy - (y1+y0)*s/2, ch)

# ---------- palette & page ----------
CREAM   = HexColor('#FBF8F3')
NAVY    = HexColor('#13202B')
ORANGE  = HexColor('#EE5A24')
GRAY    = HexColor('#6E7A83')
TAN     = HexColor('#ECE4D6')
TAN2    = HexColor('#D8D2C6')
LINEG   = HexColor('#C9CFD2')
WMARK   = HexColor('#E8E0D0')
INK     = HexColor('#1F3A52')
GOLD,  GOLD_R,  GOLD_N  = HexColor('#DB9A25'), HexColor('#B87F12'), HexColor('#8A5E0B')
SILV,  SILV_R,  SILV_N  = HexColor('#808B96'), HexColor('#66707A'), HexColor('#39434C')
BRNZ,  BRNZ_R,  BRNZ_N  = HexColor('#A0622E'), HexColor('#7F4C20'), HexColor('#5C3413')
METAL = {'3': (GOLD, GOLD_R, GOLD_N), '2': (SILV, SILV_R, SILV_N), '1': (BRNZ, BRNZ_R, BRNZ_N)}
RIBBON = {'3': ORANGE, '2': NAVY, '1': HexColor('#7A4A22')}

W, H = letter
BORDER = 10
BAR_H = 21
CX0, CX1 = 34, W-34
CW = CX1 - CX0
FOOTER = ("Questions about your player's development? Call (510) 573-4753 "
          "or ask for the facility leader \u00b7 training@hoopsphere.com")

# ---------- primitives ----------

def text(c, x, y, s, font, size, color, cs=0, align='l'):
    c.setFont(font, size)
    c.setFillColor(color)
    if not cs:
        {'l': c.drawString, 'c': c.drawCentredString, 'r': c.drawRightString}[align](x, y, s)
        return
    total = swidth(s, font, size, cs)
    if align == 'c': x -= total/2
    elif align == 'r': x -= total
    for ch in s:
        c.drawString(x, y, ch)
        x += pdfmetrics.stringWidth(ch, font, size) + cs

def swidth(s, font, size, cs=0):
    return pdfmetrics.stringWidth(s, font, size) + cs*len(s)

def page_frame(c):
    c.setFillColor(CREAM)
    c.rect(0, 0, W, H, stroke=0, fill=1)
    c.saveState()
    p = c.beginPath()
    p.rect(BORDER+1.5, BAR_H, W-2*BORDER-3, H-BORDER-BAR_H-1.5)
    c.clipPath(p, stroke=0, fill=0)
    c.setStrokeColor(WMARK)
    c.setLineWidth(1.4)
    cx, cy = W-72, 102
    for r in (58, 39, 22):
        c.circle(cx, cy, r, stroke=1, fill=0)
    c.restoreState()
    c.setStrokeColor(NAVY)
    c.setLineWidth(3)
    c.rect(BORDER, BORDER, W-2*BORDER, H-2*BORDER, stroke=1, fill=0)
    c.setFillColor(NAVY)
    c.rect(0, 0, W, BAR_H, stroke=0, fill=1)
    y = BAR_H/2 - 3.2
    x = CX0 - 8
    for seg, col in [('HOOPSPHERE ', CREAM), ('// ', ORANGE), ('BASKETBALL ACADEMY', CREAM)]:
        text(c, x, y, seg, 'BCBold', 9, col, 1)
        x += swidth(seg, 'BCBold', 9, 1)
    text(c, CX1+8, y, 'hoopsphere.com', 'BBold', 8.5, CREAM, 0.4, 'r')
    text(c, W/2, BAR_H+11, FOOTER, 'B', 8, NAVY, 0.3, 'c')

def masthead(c, pill_label, eyebrow_segments):
    top = H - BORDER - 9
    size = 56
    c.drawImage(LOGO, CX0-3, top-size, width=size, height=size, mask='auto')
    tx = CX0 + size + 11
    dy = 0 if eyebrow_segments else 7
    text(c, tx, top-22-dy, 'HOOPSPHERE', 'Anton', 26, NAVY, 0.5)
    text(c, tx+1, top-35-dy, 'BASKETBALL ACADEMY', 'BCSemi', 8.5, NAVY, 3.2)
    ey = top - 52
    x = tx + 1
    c.setStrokeColor(ORANGE)
    c.setLineWidth(1)
    for t, bw in eyebrow_segments:
        if t is not None:
            text(c, x, ey, t, 'BCSemi', 10, ORANGE, 0.8)
            x += swidth(t, 'BCSemi', 10, 0.8) + 4
        else:
            c.line(x, ey-1.5, x+bw, ey-1.5)
            x += bw + 4
    if pill_label:
        ph = 23
        pw = swidth(pill_label, 'BCBold', 9, 1.6) + 30
        py = top - 26 - dy
        c.setStrokeColor(ORANGE)
        c.setLineWidth(1.7)
        c.roundRect(CX1-pw, py, pw, ph, ph/2, stroke=1, fill=0)
        text(c, CX1-pw/2, py+ph/2-3.2, pill_label, 'BCBold', 9, ORANGE, 1.6, 'c')
    return top - size - 8

def title_row(c, y_top, title, badge=None, subtitle=None):
    ty = y_top - 26
    text(c, CX0, ty, title, 'Anton', 26, NAVY, 0.4)
    if badge:
        bh = 18
        bw = swidth(badge, 'BCBold', 8, 1) + 22
        bx, by = CX1-bw, ty-1
        c.setFillColor(ORANGE)
        p = c.beginPath()
        p.moveTo(bx, by); p.lineTo(bx+bw, by); p.lineTo(bx+bw, by+bh)
        p.lineTo(bx, by+bh); p.lineTo(bx+7, by+bh/2); p.close()
        c.drawPath(p, stroke=0, fill=1)
        text(c, bx+7+(bw-7)/2, by+bh/2-3, badge, 'BCBold', 8, CREAM, 1, 'c')
    y = ty - 6
    if subtitle:
        y -= 15
        text(c, CX0, y, subtitle, 'BSemi', 10.5, GRAY)
        y -= 3
    return y

def banner(c, y_top, content):
    items = [content] if isinstance(content, str) else list(content)
    wrapped = [simpleSplit(t, 'B', 8.9, CW - 28 - 12) for t in items]
    nl = sum(len(w) for w in wrapped)
    bh = 9 + 11 + 4 + nl*11.4 + (len(items)-1)*3.5 + 8
    y0 = y_top - bh
    c.setFillColor(NAVY)
    c.roundRect(CX0, y0, CW, bh, 9, stroke=0, fill=1)
    ty = y_top - 17
    text(c, CX0+14, ty, 'PLEASE READ FIRST \u00b7 HOW SCORING WORKS', 'BCBold', 9, ORANGE, 1.6)
    ty -= 13.2
    for w in wrapped:
        c.setFillColor(ORANGE)
        c.circle(CX0+18, ty+2.9, 2.3, stroke=0, fill=1)
        for ln in w:
            text(c, CX0+26, ty, ln, 'B', 8.9, CREAM)
            ty -= 11.4
        ty -= 3.5
    return y0


def fields_row(c, y_top, fields, h=42):
    y0 = y_top - h
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.6)
    c.roundRect(CX0, y0, CW, h, 8, stroke=1, fill=0)
    n = len(fields)
    cw = CW / n
    for i, (label, value) in enumerate(fields):
        x = CX0 + i*cw
        if i:
            c.setStrokeColor(TAN)
            c.setLineWidth(1)
            c.line(x, y0+6, x, y0+h-6)
        text(c, x+11, y_top-14, label, 'BCBold', 7.5, ORANGE, 1.4)
        c.setStrokeColor(TAN2)
        c.setLineWidth(1)
        c.line(x+11, y0+9, x+cw-11, y0+9)
        if value:
            text(c, x+11, y0+12.5, value, 'BSemi', 10.5, NAVY)
    return y0

def medal(c, cx, cy, fill, ring, numcol, ribbon, num, r=9):
    c.setFillColor(ribbon)
    for sgn in (-1, 1):
        p = c.beginPath()
        p.moveTo(cx+sgn*1.2, cy+r+6.5)
        p.lineTo(cx+sgn*5.8, cy+r+6.5)
        p.lineTo(cx+sgn*4.6, cy+r-2.5)
        p.lineTo(cx+sgn*0.6, cy+r-2.5)
        p.close()
        c.drawPath(p, stroke=0, fill=1)
    c.setFillColor(fill)
    c.setStrokeColor(ring)
    c.setLineWidth(1)
    c.circle(cx, cy, r, stroke=1, fill=1)
    centered_digit(c, cx, cy, num, 8.5, numcol)

def key_box(c, y_top, h=54):
    y0 = y_top - h
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.6)
    c.roundRect(CX0, y0, CW, h, 8, stroke=1, fill=0)
    cy = y0 + h/2
    text(c, CX0+14, cy+3, 'SCORING KEY', 'BCBold', 11.5, NAVY, 1)
    text(c, CX0+14, cy-8, 'Graded by', 'BSemi', 7.5, GRAY, 0.3)
    text(c, CX0+14, cy-17, 'age group', 'BSemi', 7.5, GRAY, 0.3)
    items = [('1', 'Building'), ('2', 'On Track'), ('3', 'Ahead')]
    x = CX0 + 205
    for num, word in items:
        fill, ring, numc = METAL[num]
        medal(c, x, cy-4, fill, ring, numc, RIBBON[num], num)
        text(c, x+16, cy+1, num, 'BBold', 11, NAVY)
        text(c, x+16, cy-11, word, 'BMed', 9, NAVY)
        x += 16 + max(swidth(word, 'BMed', 9), 12) + 52
    return y0

def section_header(c, y_top, left, right=''):
    ty = y_top - 14
    c.setFillColor(ORANGE)
    c.circle(CX0+4, ty+4, 3.6, stroke=0, fill=1)
    text(c, CX0+14, ty, left, 'Anton', 14, NAVY, 0.4)
    if right:
        text(c, CX1, ty+1, right, 'BCBold', 9, ORANGE, 0.8, 'r')
    return ty - 7

def filled_score_card(c, x, y_top, w, title, rows, scores, row_h=30, head_h=22):
    ch = head_h + len(rows)*row_h + 4
    y0 = y_top - ch
    R = 8
    c.setFillColor(NAVY)
    c.roundRect(x, y_top-head_h, w, head_h, R, stroke=0, fill=1)
    c.rect(x, y_top-head_h, w, R, stroke=0, fill=1)
    text(c, x+11, y_top-head_h+7, title, 'BCBold', 10, CREAM, 1.2)
    ry = y_top - head_h
    for j, skill in enumerate(rows):
        ry -= row_h
        cyc = ry + row_h/2
        fs = 10
        maxw = w - 96
        while swidth(skill, 'BSemi', fs) > maxw and fs > 8:
            fs -= 0.25
        text(c, x+11, cyc-3.4, skill, 'BSemi', fs, NAVY)
        s = str(scores[j])
        fill, ringc, numc = METAL[s]
        ccx = x + w - 17
        c.setFillColor(fill)
        c.setStrokeColor(ringc)
        c.setLineWidth(1)
        c.circle(ccx, cyc, 8.3, stroke=1, fill=1)
        centered_digit(c, ccx, cyc, s, 9, numc)
        if j < len(rows)-1:
            c.setStrokeColor(TAN)
            c.setLineWidth(1)
            c.line(x+11, ry, x+w-11, ry)
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.6)
    c.roundRect(x, y0, w, ch, R, stroke=1, fill=0)
    return y0

def skills_card(c, y_top, scores, row_h=46):
    ch = len(SKILLS_MAIN)*row_h + 12
    y0 = y_top - ch
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.6)
    c.roundRect(CX0, y0, CW, ch, 8, stroke=1, fill=0)
    ry = y_top - 6
    for i, (name, desc) in enumerate(SKILLS_MAIN):
        ry -= row_h
        cyc = ry + row_h/2
        text(c, CX0+14, cyc+3, name, 'BSemi', 11, NAVY)
        text(c, CX0+14, cyc-9, desc, 'B', 8.2, GRAY)
        if scores is None:
            for j, num in enumerate(('1', '2', '3')):
                ccx = CX0 + CW - 17 - (2-j)*29
                fill, ring, numc = METAL[num]
                c.setFillColor(fill)
                c.setStrokeColor(ring)
                c.setLineWidth(1)
                c.circle(ccx, cyc, 8.3, stroke=1, fill=1)
                centered_digit(c, ccx, cyc, num, 9, numc)
        else:
            sv = str(scores[name])
            fill, ring, numc = METAL[sv]
            c.setFillColor(fill)
            c.setStrokeColor(ring)
            c.setLineWidth(1)
            c.circle(CX0+CW-17, cyc, 8.3, stroke=1, fill=1)
            centered_digit(c, CX0+CW-17, cyc, sv, 9, numc)
        if i < len(SKILLS_MAIN)-1:
            c.setStrokeColor(TAN)
            c.setLineWidth(1)
            c.line(CX0+11, ry, CX0+CW-11, ry)
    return y0

REC_ROWS = [['No Changes to Your Current Schedule', 'Additional Weekly Classes'],
            ['Prep League', 'Academy League'],
            ['Elite Sessions', 'AAU Tryout']]

def rec_checklist_box(c, y_top):
    rows = len(REC_ROWS)
    bh = 10 + 13 + rows*21 + 8
    y0 = y_top - bh
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.6)
    c.roundRect(CX0, y0, CW, bh, 8, stroke=1, fill=0)
    ly = y_top - 19
    c.setFillColor(ORANGE)
    c.circle(CX0+16, ly+3.5, 3.4, stroke=0, fill=1)
    text(c, CX0+25, ly, 'OUR RECOMMENDATION', 'BCBold', 11, NAVY, 1)
    text(c, CX0+25+swidth('OUR RECOMMENDATION', 'BCBold', 11, 1)+10, ly+0.5,
         'Coach checks one', 'BItal', 8.5, GRAY)
    ty = ly - 21
    colw = (CW-28)/2
    for row in REC_ROWS:
        for i, opt in enumerate(row):
            bx = CX0 + 14 + i*colw
            c.setStrokeColor(NAVY)
            c.setLineWidth(1.2)
            c.rect(bx, ty-1.5, 10, 10, stroke=1, fill=0)
            text(c, bx+16, ty, opt, 'BSemi', 9.5, NAVY)
        ty -= 21
    return y0

def _blank_lines_box(c, y_top, label, nlines, w=None, x=None, bullets=None):
    x = CX0 if x is None else x
    w = CW if w is None else w
    bh = 10 + 13 + nlines*24 + 8
    y0 = y_top - bh
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.6)
    c.roundRect(x, y0, w, bh, 8, stroke=1, fill=0)
    ly = y_top - 19
    c.setFillColor(ORANGE)
    c.circle(x+16, ly+3.5, 3.4, stroke=0, fill=1)
    text(c, x+25, ly, label, 'BCBold', 11, NAVY, 1)
    yl = ly - 19
    for _ in range(nlines):
        lx = x + 14
        if bullets:
            if bullets == 'dot':
                c.setFillColor(ORANGE)
                c.circle(lx+3, yl+2.5, 2.8, stroke=0, fill=1)
            else:
                c.setStrokeColor(NAVY)
                c.setLineWidth(1.2)
                c.circle(lx+3, yl+2.5, 3, stroke=1, fill=0)
            lx += 13
        c.setStrokeColor(LINEG)
        c.setLineWidth(0.9)
        c.line(lx, yl, x+w-14, yl)
        yl -= 24
    return y0

def build_blank(out_path):
    """Blank AAU template: six-theme breakdown + summary page 2."""
    c = canvas.Canvas(out_path, pagesize=letter)
    c.setTitle('AAU PROGRESS REPORT')
    page_frame(c)
    y = masthead(c, 'AAU PROGRAM', [])
    y = title_row(c, y, 'AAU PROGRESS REPORT', badge='GRADED BY AGE GROUP')
    y = banner(c, y-8, BANNER_AAU)
    y = fields_row(c, y-9, [('PLAYER', None), ('DATE', None)], h=40)
    y = key_box(c, y-9, h=52)
    y = section_header(c, y-12, 'THE BREAKDOWN')
    y = skills_card(c, y, None, row_h=41)
    note_line(c, y-13, 'AAU players are graded against high-level age-group '
                       'competition, the highest bar in the academy.')
    c.showPage()
    page_frame(c)
    y = masthead(c, 'THE SUMMARY', [('AAU PROGRAM \u00b7 PROGRESS SUMMARY', None)])
    y = title_row(c, y, 'THE SUMMARY',
                  subtitle='Highlights from the last 90 days and the focus for the next 90.')
    y = _blank_lines_box(c, y-12, 'DOING WELL / IMPROVED', 3, bullets='dot')
    y = _blank_lines_box(c, y-14, 'TO WORK ON \u00b7 NEXT 90 DAYS', 3, bullets='circle')
    write_box_frame(c, y-14, 'COACH\u2019S NOTE', 4, helper='A note from the coaching staff')
    c.showPage()
    c.save()
    return out_path

def note_line(c, y, s):
    text(c, (CX0+CX1)/2, y, s, 'BSemi', 8.8, GRAY, 0, 'c')

def write_box_frame(c, y_top, label, nlines, w=None, x=None, helper=None, line_gap=24):
    x = CX0 if x is None else x
    w = CW if w is None else w
    top_pad = 10
    helper_h = 12 if helper else 0
    bh = top_pad + 13 + helper_h + nlines*line_gap + 8
    y0 = y_top - bh
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.6)
    c.roundRect(x, y0, w, bh, 8, stroke=1, fill=0)
    ly = y_top - top_pad - 9
    c.setFillColor(ORANGE)
    c.circle(x+16, ly+3.5, 3.4, stroke=0, fill=1)
    text(c, x+25, ly, label, 'BCBold', 11, NAVY, 1)
    if helper:
        ly -= 12
        text(c, x+25, ly, helper, 'BSemi', 8, GRAY, 0.2)
    ylines = []
    yline = ly - line_gap + 5
    for _ in range(nlines):
        c.setStrokeColor(LINEG)
        c.setLineWidth(0.9)
        c.line(x+14, yline, x+w-14, yline)
        ylines.append(yline)
        yline -= line_gap
    return y0, ylines

def bullet_lines(items, width_pt, fs):
    """Wrap items to lines; returns [(is_item_start, text)]."""
    out = []
    for it in items:
        lines = simpleSplit(str(it).strip(), 'BItal', fs, width_pt)
        for i, ln in enumerate(lines):
            out.append((i == 0, ln))
    return out

