def _fetch_flyer(choice):
    dest = os.path.join(tempfile.gettempdir(),
                        'hs_flyer_' + re.sub(r'\W', '_', choice) + '.pdf')
    if os.path.exists(dest) and os.path.getsize(dest) > 10000:
        return dest
    last = None
    for url in FLYER_URLS[choice]:
        try:
            _download(url, dest, attempts=3)
            if os.path.getsize(dest) > 10000:
                return dest
        except Exception as e:
            last = e
    raise ValueError(f'Could not download the {choice} flyer automatically ({last}). '
                     'Please attach that program\'s flyer PDF and pass its path as flyer_path.')

def rec_statement_box(c, y_top, choice):
    bh = 58
    y0 = y_top - bh
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.6)
    c.roundRect(CX0, y0, CW, bh, 8, stroke=1, fill=0)
    ly = y_top - 19
    c.setFillColor(ORANGE)
    c.circle(CX0+16, ly+3.5, 3.4, stroke=0, fill=1)
    text(c, CX0+25, ly, 'OUR RECOMMENDATION', 'BCBold', 11, NAVY, 1)
    program = PILL_LABEL[choice]
    ph = 21
    pw = swidth(program, 'BCBold', 10, 1.5) + 26
    px_, py_ = CX0+14, y0+11
    c.setFillColor(ORANGE)
    c.roundRect(px_, py_, pw, ph, ph/2, stroke=0, fill=1)
    text(c, px_+pw/2, py_+ph/2-3.4, program, 'BCBold', 10, CREAM, 1.5, 'c')
    if choice != 'No Changes to Your Current Schedule':
        text(c, px_+pw+13, py_+ph/2-3.2,
             'Please see the last page for program details and how to register.',
             'BItal', 9.3, GRAY)
    return y0

