# ---------- validation ----------

def _validate(data):
    errs = []
    for k in ('player', 'date', 'scores', 'doing_well', 'to_work_on'):
        if not data.get(k):
            errs.append(f"missing '{k}'")
    sc = data.get('scores', {})
    if REPORT_TYPE in ('ACADEMY', 'AAU'):
        for name, _d in SKILLS_MAIN:
            v = sc.get(name)
            if v not in (1, 2, 3):
                errs.append(f"scores['{name}'] must be 1, 2, or 3 (got {v!r})")
        for k in ('doing_well', 'to_work_on'):
            if isinstance(data.get(k), str):
                data[k] = [data[k]]
            v = data.get(k)
            if not isinstance(v, (list, tuple)) or len(v) != 1:
                errs.append(f"'{k}' must be exactly one item on this report")
    else:
        cards = CARDS[REPORT_TYPE]
        for title, rows in cards:
            vals = sc.get(title)
            if not isinstance(vals, (list, tuple)) or len(vals) != len(rows):
                errs.append(f"scores['{title}'] must be a list of {len(rows)} values (rows: {rows})")
                continue
            for v in vals:
                if v not in (1, 2, 3):
                    errs.append(f"scores['{title}'] contains {v!r}; only 1, 2, 3 allowed")
    if REPORT_TYPE in ('STANDARD', 'FOUNDATIONS', 'ACADEMY'):
        if data.get('recommendation') not in REC_CHOICES:
            errs.append(f"'recommendation' must be exactly one of: {REC_CHOICES}")
        if not data.get('why'):
            errs.append("missing 'why'")
    else:
        if not data.get('coachs_note'):
            errs.append("missing 'coachs_note'")
    if errs:
        raise ValueError('Cannot generate report: ' + '; '.join(errs))

def _check_flyer(flyer_path, choice):
    kw = FLYER_KEYWORD[choice]
    try:
        out = subprocess.run(['pdftotext', '-l', '1', flyer_path, '-'],
                             capture_output=True, text=True, check=True).stdout
    except Exception as e:
        raise ValueError(f'Could not read the attached flyer PDF: {e}')
    flat = re.sub(r'\s+', '', out).upper()
    if kw not in flat:
        raise ValueError(f'Attached flyer does not look like the {choice} flyer. '
                         'Please attach the correct program flyer.')

# ---------- pages ----------

def _page1(c, data):
    page_frame(c)
    if REPORT_TYPE == 'AAU':
        y = masthead(c, 'AAU PROGRAM', [])
        y = title_row(c, y, 'AAU PROGRESS REPORT', badge='GRADED BY AGE GROUP')
        y = banner(c, y-8, BANNER_AAU)
        y = fields_row(c, y-9, [('PLAYER', data['player'] if data else None),
                                ('DATE', data['date'] if data else None)], h=40)
        y = key_box(c, y-9, h=52)
        y = section_header(c, y-12, 'THE BREAKDOWN')
        y = skills_card(c, y, data['scores'] if data else None, row_h=41)
        note_line(c, y-13, 'AAU players are graded against high-level age-group '
                           'competition, the highest bar in the academy.')
        return
    if REPORT_TYPE == 'ACADEMY':
        y = masthead(c, None, [])
        y = title_row(c, y, 'PLAYER PROGRESS REPORT', badge='GRADED BY AGE GROUP')
        y = banner(c, y-8, BANNER_STANDARD)
        y = fields_row(c, y-10, [('PLAYER', data['player'] if data else None),
                                 ('DATE', data['date'] if data else None)])
        y = key_box(c, y-10)
        y = section_header(c, y-13, 'THE BREAKDOWN')
        y = skills_card(c, y, data['scores'] if data else None)
        note_line(c, y-15, 'Every skill is graded against your player\u2019s own age group. '
                           'The bar rises as they move up.')
        return
    raise ValueError('Unsupported REPORT_TYPE for this generator: %s' % REPORT_TYPE)

def _fill_bulleted_box(c, y_top, label, items, w, x, bullet):
    fs = 8.9 if w < CW else 9.3
    avail = w - 44
    lines = bullet_lines(items, avail, fs)
    n = max(3, len(lines))
    y0, ylines = write_box_frame(c, y_top, label, n, w=w, x=x)
    for (start, ln), yl in zip(lines, ylines):
        lx = x + 14
        if start:
            if bullet == 'dot':
                c.setFillColor(ORANGE)
                c.circle(lx+3, yl+2.5, 2.8, stroke=0, fill=1)
            else:
                c.setStrokeColor(NAVY)
                c.setLineWidth(1.2)
                c.circle(lx+3, yl+2.5, 3, stroke=1, fill=0)
        text(c, lx+16, yl+2.5, ln, 'BItal', fs, INK)
    return y0

def _fill_para_box(c, y_top, label, body, w=None, x=None, helper=None, fs=9.3):
    x = CX0 if x is None else x
    w = CW if w is None else w
    lines = simpleSplit(str(body).strip(), 'BItal', fs, w - 32)
    n = max(3, len(lines))
    y0, ylines = write_box_frame(c, y_top, label, n, w=w, x=x, helper=helper)
    for ln, yl in zip(lines, ylines):
        text(c, x+15, yl+2.5, ln, 'BItal', fs, INK)
    return y0

def _page2(c, data):
    page_frame(c)
    if REPORT_TYPE == 'AAU':
        y = masthead(c, 'THE SUMMARY', [('AAU PROGRAM  \u00b7  PROGRESS SUMMARY', None)])
        y = title_row(c, y, 'THE SUMMARY',
                      subtitle='Highlights from the last 90 days and the focus for the next 90.')
        y = _fill_bulleted_box(c, y-12, 'DOING WELL / IMPROVED', data['doing_well'], CW, CX0, 'dot')
        y = _fill_bulleted_box(c, y-14, 'TO WORK ON \u00b7 NEXT 90 DAYS', data['to_work_on'], CW, CX0, 'circle')
        _fill_para_box(c, y-14, 'COACH\u2019S NOTE', data['coachs_note'],
                       helper='A note from the coaching staff')
    else:
        y = masthead(c, 'YOUR NEXT STEP', [('PROGRESS REPORT', None)])
        y = title_row(c, y, 'YOUR NEXT STEP',
                      subtitle='A summary of the last 90 days and where your player goes from here.')
        y = rec_statement_box(c, y-12, data['recommendation'])
        y = _fill_para_box(c, y-14, 'WHY WE RECOMMEND IT', data['why'])
        gap = 15
        cw2 = (CW-gap)/2
        _fill_bulleted_box(c, y-14, 'DOING WELL / IMPROVED', data['doing_well'], cw2, CX0, 'dot')
        _fill_bulleted_box(c, y-14, 'TO WORK ON \u00b7 NEXT 90 DAYS', data['to_work_on'], cw2,
                           CX0+cw2+gap, 'circle')

# ---------- generate ----------

def generate(data, flyer_path=None, out_dir='/mnt/user-data/outputs'):
    _validate(data)
    needs_flyer = (REPORT_TYPE in ('STANDARD', 'FOUNDATIONS', 'ACADEMY')
                   and data['recommendation'] != 'No Changes to Your Current Schedule')
    if needs_flyer:
        if not flyer_path or not os.path.exists(str(flyer_path)):
            flyer_path = _fetch_flyer(data['recommendation'])
        _check_flyer(flyer_path, data['recommendation'])
    os.makedirs(out_dir, exist_ok=True)
    body = os.path.join(tempfile.gettempdir(), 'hs_report_body.pdf')
    c = canvas.Canvas(body, pagesize=letter)
    c.setTitle('AAU PROGRESS REPORT' if REPORT_TYPE == 'AAU' else 'PLAYER PROGRESS REPORT')
    _page1(c, data)
    c.showPage()
    _page2(c, data)
    c.showPage()
    c.save()
    safe = re.sub(r'[^A-Za-z0-9 .\-\']', '', str(data['player'])).strip()
    out = os.path.join(out_dir, f'{safe} - Player Progress Report.pdf')
    if needs_flyer:
        try:
            _ensure('pikepdf')
            import pikepdf
            pdf = pikepdf.open(body)
            fl = pikepdf.open(str(flyer_path))
            pdf.pages.extend(fl.pages)
            pdf.save(out)
        except Exception:
            # last resort only: pdfunite merges but drops hyperlinks
            subprocess.run(['pdfunite', body, str(flyer_path), out], check=True)
    else:
        import shutil
        shutil.copyfile(body, out)
    return out
